import xmltodict

def test_converts_sample_order():
    order = {
        "order": {
            "@id": "1001",
            "customer": "Alice",
            "items": {
                "item": [
                    {"@sku": "WM-001", "name": "Wireless Mouse", "qty": "1"},
                    {"@sku": "KB-002", "name": "Keyboard", "qty": "2"}
                ]
            },
            "total": "109.97"
        }
    }
    result = exercise.order_to_xml(order)
    parsed = xmltodict.parse(result)
    assert parsed["order"]["@id"] == "1001", f"Expected order id '1001', got {parsed['order'].get('@id')}"
    assert parsed["order"]["customer"] == "Alice", f"Expected customer 'Alice', got {parsed['order'].get('customer')}"
    items = parsed["order"]["items"]["item"]
    assert len(items) == 2, f"Expected 2 items, got {len(items)}"
    assert items[0]["@sku"] == "WM-001", f"Expected first item sku 'WM-001', got {items[0].get('@sku')}"

def test_returns_string():
    result = exercise.order_to_xml({"root": {"value": "test"}})
    assert isinstance(result, str), f"Expected string, got {type(result)}"

def test_simple_dict_conversion():
    data = {"book": {"title": "Python 101", "author": "Alice"}}
    result = exercise.order_to_xml(data)
    parsed = xmltodict.parse(result)
    assert parsed["book"]["title"] == "Python 101", f"Expected title 'Python 101', got {parsed['book'].get('title')}"
    assert parsed["book"]["author"] == "Alice", f"Expected author 'Alice', got {parsed['book'].get('author')}"

def test_xml_declaration_present():
    result = exercise.order_to_xml({"root": {"x": "1"}})
    assert result.strip().startswith("<?xml"), f"Expected XML declaration at start, got {result[:50]!r}"

